package com.example.ui.localization

/**
 * Whole-phrase copy for the Hajj & Umrah guide (steps, duas, counters, essentials).
 * Keys are the English strings in HajjUmrahGuide.kt and HajjUmrahScreen.kt.
 */
internal val hajjUmrahPhrases: Map<String, Map<String, String>> = mapOf(
    "hinglish" to mapOf(
        // Screen
        "Essentials" to "Zaroori baatein", "Your Umrah" to "Aapka Umrah", "Your Hajj" to "Aapka Hajj",
        "steps done" to "qadam mukammal", "Next step" to "Agla qadam", "Start again" to "Dobara shuru karein",
        "Start again?" to "Dobara shuru karein?",
        "This clears the ticked steps and round counters for this guide." to "Is guide ke tick kiye hue qadam aur chakkar ki ginti mit jayegi.",
        "All steps done. May Allah accept it from you!" to "Saare qadam mukammal. Allah aap se qubool farmaye!",
        "Tap a step to see how to do it, its dua and a round counter. Tick it when done — your progress is saved on this phone." to "Kisi qadam par tap karein: tareeqa, dua aur chakkar counter dekhein. Poora hone par tick karein — aapki progress isi phone mein save rehti hai.",
        "Rulings follow Hanafi fiqh. Learn the masail from a reliable Sunni scholar and follow your licensed group." to "Ahkaam Hanafi fiqh ke mutabiq hain. Masail kisi mo'tabar Sunni aalim se seekhein aur apne licensed group ki hidayat par chalein.",
        "Expand" to "Kholein", "Collapse" to "Band karein",
        "Mark step as done" to "Qadam mukammal karein", "Mark as not done" to "Namukammal karein",
        "Recite" to "Padhein",
        "Round counter" to "Chakkar counter", "Pebble counter" to "Kankari counter",
        "Round" to "Chakkar", "Pebble" to "Kankari", "Count round" to "Chakkar ginein", "Count pebble" to "Kankari ginein",
        "Saved automatically, even if you close the app." to "App band ho jaye tab bhi ginti khud save rehti hai.",
        "Type of Hajj" to "Hajj ki qism",
        "Most pilgrims from the subcontinent perform Tamattu'. In Hanafi fiqh Qiran is the most virtuous, then Tamattu', then Ifrad. Each type keeps its own progress." to "Bar-e-sagheer ke zyada tar hujjaj Tamattu' karte hain. Hanafi fiqh mein Qiran sab se afzal hai, phir Tamattu', phir Ifrad. Har qism ki progress alag save hoti hai.",
        "ready" to "tayyar",

        // Rulings and Hajj types
        "Condition" to "Shart", "Fard" to "Farz", "Wajib" to "Wajib", "Sunnah" to "Sunnat",
        "Tamattu'" to "Tamattu'", "Qiran" to "Qiran", "Ifrad" to "Ifrad",
        "Umrah first in the months of Hajj, leave ihram, then a fresh ihram for Hajj on the 8th. Qurbani is wajib." to "Hajj ke mahinon mein pehle Umrah, phir ihram khol dein, aur 8 tareekh ko Hajj ka naya ihram. Qurbani wajib hai.",
        "One ihram for Umrah and Hajj together, kept on until Halq on the 10th. Qurbani is wajib." to "Umrah aur Hajj dono ka ek hi ihram, jo 10 tareekh ke Halq tak rehta hai. Qurbani wajib hai.",
        "Ihram for Hajj only, without Umrah. Qurbani is recommended, not wajib." to "Sirf Hajj ka ihram, Umrah ke baghair. Qurbani mustahab hai, wajib nahi.",

        // Counter hints
        "Tawaf complete. Now pray the two rakat." to "Tawaf mukammal. Ab do rakat padhein.",
        "Raml: men walk briskly with short steps" to "Raml: mard chhote qadmon se akad kar tez chalein",
        "Walk at a normal pace" to "Aam raftaar se chalein",
        "Sa'i complete. It ends at Marwah." to "Sa'i mukammal. Yeh Marwah par khatm hoti hai.",
        "Safa → Marwah" to "Safa → Marwah", "Marwah → Safa" to "Marwah → Safa",
        "All seven pebbles thrown" to "Saaton kankariyan maar di gayin",
        "Jamrat al-Aqabah (big)" to "Jamrat-ul-Aqabah (bada)",
        "Jamrah Ula (small)" to "Jamrah Ula (chhota)", "Jamrah Wusta (middle)" to "Jamrah Wusta (darmiyani)",
        "Make dua facing the Qibla, then go to the Wusta" to "Qibla rukh ho kar dua karein, phir Wusta ki taraf jayein",
        "Make dua facing the Qibla, then go to the Aqabah" to "Qibla rukh ho kar dua karein, phir Aqabah ki taraf jayein",
        "All three Jamarat done for today" to "Aaj ke teenon Jamarat mukammal",

        // Dua meanings
        "Our Lord, give us good in this world and good in the Hereafter, and save us from the punishment of the Fire. (Between Rukn Yamani and the Black Stone)" to "Aye hamare Rab, humein dunya mein bhi bhalai de aur aakhirat mein bhi bhalai de, aur humein aag ke azaab se bacha. (Rukn-e-Yamani aur Hajr-e-Aswad ke darmiyan)",
        "And take the Station of Ibrahim as a place of prayer." to "Aur Maqam-e-Ibrahim ko namaz ki jagah banao.",
        "Indeed, Safa and Marwah are among the symbols of Allah. (Recited on first reaching Safa)" to "Beshak Safa aur Marwah Allah ki nishaniyon mein se hain. (Pehli baar Safa par pahunch kar padhein)",
        "None has the right to be worshipped but Allah alone, without partner. His is the dominion and His is the praise, and He has power over all things." to "Allah ke siwa koi mabood nahi, woh akela hai, uska koi shareek nahi. Usi ki badshahat hai aur usi ki tareef, aur woh har cheez par qaadir hai.",
        "When you depart from Arafat, remember Allah at al-Mash'ar al-Haram." to "Jab tum Arafat se lauto to Mash'ar-ul-Haram ke paas Allah ko yaad karo.",
        "Allah is the Greatest. (With every pebble)" to "Allah sab se bada hai. (Har kankari ke saath)",
        "And let them circle the Ancient House." to "Aur woh is qadeem ghar (Kaaba) ka tawaf karein.",
        "Blessings and peace be upon you, O Messenger of Allah." to "Aap par durood aur salaam ho, Ya Rasool Allah.",

        // Umrah points
        "Men wear two plain unstitched sheets; women wear their normal modest clothes." to "Mard do saada be-sile chaadarein pehnein; auratein apne aam parde wale kapde pehnein.",
        "Pray two rakat nafl with the head covered, outside the makruh times." to "Sar dhaanp kar do rakat nafl padhein, makruh auqaat ke ilawa.",
        "Uncover the head, make the niyyah of Umrah and say the Talbiyah. Ihram begins with niyyah and Talbiyah together." to "Sar khol kar Umrah ki niyyat karein aur Talbiyah padhein. Ihram niyyat aur Talbiyah dono se shuru hota hai.",
        "Keep reciting the Talbiyah until you begin the Tawaf." to "Tawaf shuru karne tak Talbiyah padhte rahein.",
        "Wudu is required for Tawaf." to "Tawaf ke liye wuzu zaroori hai.",
        "Men: Idtiba throughout this Tawaf — the upper sheet under the right arm, right shoulder bare." to "Mard: is poore Tawaf mein Iztiba — oopar ki chaadar daayein baghal ke neeche se, daayan kandha khula.",
        "Begin at the Black Stone line: kiss it, touch it, or simply raise your palms towards it and say Bismillah, Allahu Akbar." to "Hajr-e-Aswad ki line se shuru karein: bosa dein, chhooyein, ya sirf hatheliyan us ki taraf utha kar Bismillah, Allahu Akbar kahein.",
        "Men do Raml (brisk short steps) in the first three rounds." to "Mard pehle teen chakkaron mein Raml (chhote qadmon se tez chalna) karein.",
        "Go around the Hatim, never through it, and keep your chest from turning towards the Kaaba." to "Hateem ke bahar se ghoomein, andar se hargiz nahi, aur apna seena Kaaba ki taraf na ghumayein.",
        "Cover both shoulders again before praying." to "Namaz se pehle dono kandhe dobara dhaanp lein.",
        "Sunnah: Surah al-Kafirun in the first rakah and al-Ikhlas in the second." to "Sunnat: pehli rakat mein Surah al-Kafirun aur doosri mein al-Ikhlas.",
        "Make dua at the Multazam, then drink Zamzam standing, facing the Qibla." to "Multazam par dua karein, phir Qibla rukh khade ho kar Zamzam piyein.",
        "Safa to Marwah is one round; Marwah back to Safa is the second." to "Safa se Marwah ek chakkar hai; Marwah se wapas Safa doosra.",
        "On Safa and Marwah face the Kaaba, raise your hands as in dua, and praise Allah." to "Safa aur Marwah par Kaaba ki taraf rukh karein, dua ki tarah haath uthayein aur Allah ki hamd karein.",
        "Men jog lightly between the green lights; women walk normally." to "Hari battiyon ke darmiyan mard halka daudein; auratein aam chaal chalein.",
        "Wudu is recommended for Sa'i but not required." to "Sa'i ke liye wuzu mustahab hai, zaroori nahi.",
        "Shaving is better for men: the Prophet ﷺ prayed three times for those who shave." to "Mardon ke liye sar mundwana afzal hai: Nabi ﷺ ne mundwane walon ke liye teen baar dua farmayi.",
        "Trimming must cover at least a quarter of the head, a fingertip's length; the whole head is better." to "Baal katwane mein kam az kam chauthai sar se ungli ke pore barabar kaatein; poore sar se behtar hai.",
        "Do it inside the Haram. Your Umrah is complete — may Allah accept it." to "Yeh Haram ki hudood mein karein. Aapka Umrah mukammal — Allah qubool farmaye.",

        // Hajj steps
        "Before 8 Dhul Hijjah" to "8 Zil Hijjah se pehle", "At the miqat" to "Miqat par", "On reaching Makkah" to "Makkah pahunch kar",
        "11–12 Dhul Hijjah" to "11–12 Zil Hijjah", "Before leaving Makkah" to "Makkah se rawangi se pehle",
        "Umrah of Tamattu'" to "Tamattu' ka Umrah", "Ihram of Qiran" to "Qiran ka ihram", "Ihram of Ifrad" to "Ifrad ka ihram",
        "Umrah Tawaf and Sa'i, then Tawaf al-Qudum" to "Umrah ka Tawaf aur Sa'i, phir Tawaf-e-Qudoom",
        "Tawaf al-Qudum" to "Tawaf-e-Qudoom", "Wuquf at Arafat" to "Wuqoof-e-Arafat", "Rami and Halq" to "Rami aur Halq",
        "Rami of the three Jamarat" to "Teenon Jamarat ki Rami",
        "Enter ihram at the miqat with the niyyah of Umrah, perform the full Umrah, then shave or trim and leave ihram. Stay in Makkah until the 8th." to "Miqat par Umrah ki niyyat se ihram baandhein, poora Umrah karein, phir Halq ya Qasr kar ke ihram khol dein. 8 tareekh tak Makkah mein rahein.",
        "Follow the Umrah tab step by step." to "Umrah tab ke mutabiq qadam ba qadam chalein.",
        "Keep away from sin; use these days for Tawaf, Quran and dua." to "Gunahon se bachein; yeh din Tawaf, Quran aur dua mein guzarein.",
        "Make the niyyah of both Umrah and Hajj together and recite the Talbiyah. This ihram stays on until Halq on the 10th." to "Umrah aur Hajj dono ki ek saath niyyat karein aur Talbiyah padhein. Yeh ihram 10 tareekh ke Halq tak rahega.",
        "Perform the Tawaf and Sa'i of Umrah but do not shave. Then perform Tawaf al-Qudum; you may do the Sa'i of Hajj after it." to "Umrah ka Tawaf aur Sa'i karein magar baal na katwayein. Phir Tawaf-e-Qudoom karein; is ke baad Hajj ki Sa'i bhi kar sakte hain.",
        "Stay in ihram and keep reciting the Talbiyah after the Umrah." to "Umrah ke baad bhi ihram mein rahein aur Talbiyah padhte rahein.",
        "Make the niyyah of Hajj only and recite the Talbiyah. This ihram stays on until Halq on the 10th." to "Sirf Hajj ki niyyat karein aur Talbiyah padhein. Yeh ihram 10 tareekh ke Halq tak rahega.",
        "The arrival Tawaf, Sunnah for pilgrims from outside the miqat. You may do the Sa'i of Hajj after it." to "Aamad ka Tawaf, miqat ke bahar se aane walon ke liye Sunnat. Is ke baad Hajj ki Sa'i kar sakte hain.",
        "If you will do Sa'i after it, men do Raml and Idtiba in this Tawaf." to "Agar is ke baad Sa'i karni hai to mard is Tawaf mein Raml aur Iztiba karein.",
        "Put on ihram in Makkah with the niyyah of Hajj, recite the Talbiyah and go to Mina. Pray Dhuhr to the next Fajr there." to "Makkah mein Hajj ki niyyat se ihram baandhein, Talbiyah padhein aur Mina jayein. Wahan Zuhr se agli Fajr tak namazein padhein.",
        "Stay in your ihram and go to Mina with the Talbiyah. Pray Dhuhr to the next Fajr there." to "Apne ihram mein rehte hue Talbiyah ke saath Mina jayein. Wahan Zuhr se agli Fajr tak namazein padhein.",
        "Staying in Mina on the 8th and the night of the 9th is Sunnah." to "8 tareekh aur 9 ki raat Mina mein rehna Sunnat hai.",
        "Recite the Talbiyah often." to "Kasrat se Talbiyah padhein.",
        "Being in Arafat for any moment from zawal on the 9th until dawn of the 10th fulfils the fard; staying until sunset is wajib." to "9 ke zawal se 10 ki subah-e-sadiq tak ek lamha bhi Arafat mein hona farz ada kar deta hai; suraj doobne tak rukna wajib hai.",
        "Hanafi: Dhuhr and Asr are combined only behind the Imam of Hajj at Masjid Namirah. In your tent, pray each at its own time." to "Hanafi: Zuhr aur Asr sirf Masjid-e-Namirah mein Imam-e-Hajj ke peechhe jama hoti hain. Khaime mein har namaz apne waqt par padhein.",
        "Stay inside the boundary markers of Arafat." to "Arafat ki hudood ke nishanon ke andar rahein.",
        "Spend the afternoon standing in dua, istighfar and Talbiyah, facing the Qibla." to "Zawal ke baad ka waqt Qibla rukh khade ho kar dua, istighfar aur Talbiyah mein guzarein.",
        "Leaving Arafat before sunset makes a Dam due, unless you return before sunset." to "Suraj doobne se pehle Arafat chhodne par Dam wajib hai, jab tak ghuroob se pehle wapas na aa jayein.",
        "Leave Arafat after sunset without praying Maghrib. At Muzdalifah pray Maghrib and Isha together in Isha time and spend the night there." to "Suraj doobne ke baad Maghrib padhe baghair Arafat se niklein. Muzdalifah mein Isha ke waqt Maghrib aur Isha ek saath padhein aur raat wahin guzarein.",
        "The wajib wuquf is between dawn and sunrise on the 10th: pray Fajr early and stay in dhikr." to "Wajib wuqoof 10 tareekh ki subah-e-sadiq se suraj nikalne tak hai: Fajr jaldi padh kar zikr mein rahein.",
        "Pick up chickpea-sized pebbles: 49 in all, or 70 if you will stay for the 13th." to "Chane ke daane jitni kankariyan chunein: kul 49, ya 13 tareekh rukna ho to 70.",
        "The sick, elderly and weak may leave after midnight because of the crowd, with no penalty." to "Beemar, boodhe aur kamzor bheed ki wajah se aadhi raat ke baad ja sakte hain, un par koi dam nahi.",
        "Stone only Jamrat al-Aqabah (the big one) with seven pebbles, one at a time. Stop the Talbiyah with the first pebble." to "Sirf Jamrat-ul-Aqabah (bade) ko saat kankariyan, ek ek kar ke maarein. Pehli kankari ke saath Talbiyah band kar dein.",
        "Then offer the Qurbani (Dam-e-Shukr), then shave or trim. Hanafi: this order is wajib; breaking it makes a Dam due." to "Phir Qurbani (Dam-e-Shukr) karein, phir Halq ya Qasr. Hanafi: yeh tarteeb wajib hai; tootne par Dam wajib hota hai.",
        "Then shave or trim. Qurbani is recommended for Ifrad; if you offer it, do so before Halq." to "Phir Halq ya Qasr karein. Ifrad mein Qurbani mustahab hai; karein to Halq se pehle karein.",
        "The Sunnah time for this Rami is from sunrise until zawal." to "Is Rami ka masnoon waqt suraj nikalne se zawal tak hai.",
        "After Halq everything forbidden in ihram becomes lawful except marital relations, until Tawaf al-Ziyarah." to "Halq ke baad ihram ki saari pabandiyan khatm, siwaye miyan biwi ke ta'alluq ke, jo Tawaf-e-Ziyarat tak mana hai.",
        "The obligatory Tawaf of Hajj. Perform it after Halq, best on the 10th, and before sunset on the 12th." to "Hajj ka farz Tawaf. Halq ke baad karein, behtar 10 tareekh ko, aur 12 ke ghuroob se pehle.",
        "Then perform the Sa'i of Hajj between Safa and Marwah." to "Phir Safa aur Marwah ke darmiyan Hajj ki Sa'i karein.",
        "Perform the Sa'i of Hajj now if you did not do it after Tawaf al-Qudum." to "Agar Tawaf-e-Qudoom ke baad Hajj ki Sa'i nahi ki thi to ab karein.",
        "Delaying it past the 12th without excuse makes a Dam due. A woman in her period waits until she is pure, with no penalty." to "Baghair uzr 12 ke baad tak der karne par Dam wajib hai. Haiz wali aurat paak hone tak intezar kare, us par koi dam nahi.",
        "After this Tawaf, marital relations also become lawful." to "Is Tawaf ke baad miyan biwi ka ta'alluq bhi halal ho jata hai.",
        "Spend the days in Mina. Each day after zawal stone all three — Ula, Wusta, then Aqabah — with seven pebbles each." to "Yeh din Mina mein guzarein. Har din zawal ke baad teenon — Ula, Wusta, phir Aqabah — ko saat saat kankariyan maarein.",
        "After the Ula and the Wusta, step aside, face the Qibla and make a long dua. Do not stop for dua after the Aqabah." to "Ula aur Wusta ke baad ek taraf ho kar Qibla rukh lambi dua karein. Aqabah ke baad dua ke liye na rukein.",
        "You may leave Mina on the 12th before sunset. If you are still in Mina at dawn on the 13th, the Rami of the 13th becomes wajib." to "12 tareekh ko ghuroob se pehle Mina chhod sakte hain. Agar 13 ki subah-e-sadiq Mina mein hui to 13 ki Rami wajib ho jati hai.",
        "The sick and the weak who cannot reach the Jamarat may appoint someone to stone for them." to "Jo beemar aur kamzor Jamarat tak nahi pahunch sakte woh kisi ko apni taraf se Rami ke liye naib bana sakte hain.",
        "Reset the counter each day." to "Har din counter reset karein.",
        "Tawaf al-Wida, wajib for pilgrims from outside the miqat. Make it your last act in Makkah." to "Tawaf-e-Wida, miqat ke bahar se aane walon par wajib. Isey Makkah mein apna aakhri amal banayein.",
        "No Raml, Idtiba or Sa'i in this Tawaf." to "Is Tawaf mein na Raml, na Iztiba, na Sa'i.",
        "A woman in her period is excused from it." to "Haiz wali aurat ko is ki chhoot hai.",
        "Drink Zamzam, make dua at the Multazam and leave with a heart longing to return." to "Zamzam piyein, Multazam par dua karein aur dobara aane ki tamanna ke saath rukhsat hon.",

        // Essentials
        "Fard and Wajib" to "Faraiz aur Wajibat", "What makes Hajj and Umrah valid" to "Hajj aur Umrah kin cheezon se sahih hote hain",
        "Hajj fard: Ihram, Wuquf at Arafat, Tawaf al-Ziyarah. Missing one cannot be made up by Dam." to "Hajj ke farz: Ihram, Wuqoof-e-Arafat, Tawaf-e-Ziyarat. Inmein se koi chhoot jaye to Dam se poora nahi hota.",
        "Hajj wajib: Muzdalifah, Sa'i, Rami, Qurbani for Qiran and Tamattu', Halq or Qasr, Tawaf al-Wida." to "Hajj ke wajibat: Muzdalifah, Sa'i, Rami, Qiran aur Tamattu' mein Qurbani, Halq ya Qasr, Tawaf-e-Wida.",
        "Umrah: Ihram is the condition and Tawaf is fard; Sa'i and Halq or Qasr are wajib." to "Umrah: Ihram shart hai aur Tawaf farz; Sa'i aur Halq ya Qasr wajib hain.",
        "Missing a wajib without a valid excuse makes a Dam due: one goat or sheep slaughtered within the Haram." to "Baghair sharai uzr koi wajib chhootne par Dam wajib hai: Haram ki hudood mein ek bakri ya bheid ki qurbani.",
        "Crossing the miqat towards Makkah without ihram makes a Dam due, unless you go back and enter ihram there." to "Baghair ihram miqat se Makkah ki taraf guzarne par Dam wajib hai, jab tak wapas ja kar wahan se ihram na baandhein.",
        "Rules of ihram" to "Ihram ke ahkaam", "What is forbidden and what is allowed" to "Kya mana hai aur kya jaaiz",
        "Perfume or scented soap on the body or the ihram" to "Jism ya ihram par khushboo ya khushboodar sabun",
        "Cutting or removing hair or nails" to "Baal ya nakhun kaatna ya todna",
        "Marital relations and anything leading to them" to "Miyan biwi ka ta'alluq aur us ki taraf le jaane wali har baat",
        "Hunting, or helping someone hunt" to "Shikar karna ya shikar mein madad karna",
        "Arguing, fighting and sinful speech" to "Jhagda, ladai aur gunah ki baatein",
        "Covering the face, for men and women" to "Chehra dhaanpna, mard aur aurat dono ke liye",
        "Men: stitched clothes, covering the head, and shoes that cover the raised bone on top of the foot" to "Mard: sile hue kapde, sar dhaanpna, aur aise joote jo pair ke oopar ki ubhri haddi dhaanp lein",
        "Women: gloves, or a veil touching the face — a cap visor keeps it off the face" to "Auratein: dastane, ya chehre ko chhoota hua naqab — cap ka chhajja naqab ko chehre se door rakhta hai",
        "Bathing without scented soap" to "Baghair khushboo ke sabun se nahana",
        "Changing or washing the ihram sheets" to "Ihram ki chaadarein badalna ya dhona",
        "An umbrella, belt, wallet, watch and glasses" to "Chhatri, belt, batua, ghadi aur chashma",
        "Women: normal stitched clothes, socks and shoes" to "Auratein: aam sile kapde, moze aur joote",
        "For women" to "Khawateen ke liye", "Masail specific to sisters" to "Behnon ke khaas masail",
        "A mahram must accompany a woman on the journey." to "Safar mein aurat ke saath mahram ka hona zaroori hai.",
        "Recite the Talbiyah quietly." to "Talbiyah aahista awaaz mein padhein.",
        "No Raml, no Idtiba and no jogging between the green lights." to "Na Raml, na Iztiba, na hari battiyon ke darmiyan daudna.",
        "Trim a fingertip's length from the ends of the hair; never shave." to "Baalon ke siron se ungli ke pore barabar kaatein; sar hargiz na mundwayein.",
        "During menses do every rite except Tawaf and its two rakat." to "Haiz mein Tawaf aur us ki do rakat ke siwa saare arkaan ada karein.",
        "Tawaf al-Wida is waived for a woman in her period." to "Haiz wali aurat se Tawaf-e-Wida saaqit hai.",
        "Common mistakes" to "Aam ghaltiyan", "Protect your Hajj and Umrah" to "Apne Hajj aur Umrah ki hifazat karein",
        "Keeping the right shoulder bare the whole time — Idtiba is only during Tawaf" to "Poore waqt daayan kandha khula rakhna — Iztiba sirf Tawaf mein hai",
        "Pushing or hurting people to kiss the Black Stone — pointing is enough" to "Hajr-e-Aswad ka bosa lene ke liye logon ko dhakka dena ya takleef dena — ishara kaafi hai",
        "Walking through the Hatim — it is part of the Kaaba" to "Hateem ke andar se guzarna — yeh Kaaba ka hissa hai",
        "Doing Tawaf without wudu" to "Baghair wuzu Tawaf karna",
        "Leaving Arafat before sunset" to "Suraj doobne se pehle Arafat chhodna",
        "Throwing large stones, shoes, or all seven pebbles at once" to "Bade pathar, joote, ya saaton kankariyan ek saath maarna",
        "Spending precious time on the phone instead of dua" to "Dua ke bajaye qeemti waqt phone par guzarna",
        "Preparation checklist" to "Tayyari ki checklist",
        "Heart and rights" to "Dil aur huqooq", "Documents" to "Kaaghzaat", "Packing" to "Samaan",
        "Sincere tauba and a pure niyyah" to "Sachchi tauba aur khaalis niyyat",
        "Repay debts and settle others' rights" to "Qarz ada karein aur logon ke huqooq chukayein",
        "Write your wasiyyat (will)" to "Apni wasiyyat likh lein",
        "Use only halal money for the journey" to "Safar ke liye sirf halal maal istemal karein",
        "Learn the masail from a Sunni scholar" to "Kisi Sunni aalim se masail seekhein",
        "Passport, visa and Hajj or Umrah permit" to "Passport, visa aur Hajj ya Umrah permit",
        "Meningitis (ACWY) vaccination certificate" to "Meningitis (ACWY) teeke ka certificate",
